  `customer_id` bigint(20) unsigned NOT NULL,
  `address_id` bigint(20) unsigned DEFAULT NULL,
  `location_id` varchar(64) NOT NULL,
  `channel` varchar(10) NOT NULL DEFAULT 'web',
  `from_app` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(12) NOT NULL DEFAULT 'new',
  `address` varchar(255) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `pay_method` varchar(10) NOT NULL DEFAULT 'cash',
  `collection_method` varchar(20) DEFAULT NULL,
  `collected_amount` decimal(12,2) DEFAULT NULL,
  `collected_by` char(36) DEFAULT NULL,
  `collected_at` timestamp NULL DEFAULT NULL,
  `sale_id` bigint(20) unsigned DEFAULT NULL,
  `reservation_id` bigint(20) unsigned DEFAULT NULL,
  `est_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(12,2) DEFAULT NULL,
  `delivery_fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total` decimal(12,2) DEFAULT NULL,
  `paid` tinyint(1) NOT NULL DEFAULT 0,
  `driver` varchar(255) DEFAULT NULL,
  `driver_id` char(36) DEFAULT NULL,
  `cancel_reason` text DEFAULT NULL,
  `handled_by` char(36) DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `ready_at` timestamp NULL DEFAULT NULL,
  `out_at` timestamp NULL DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `online_orders_no_unique` (`no`),
  UNIQUE KEY `online_orders_token_unique` (`token`),
  KEY `online_orders_customer_id_foreign` (`customer_id`),
  KEY `online_orders_location_id_status_index` (`location_id`,`status`),
  CONSTRAINT `online_orders_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `online_orders_location_id_foreign` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=212 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `override_requests`;
CREATE TABLE `override_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(10) NOT NULL,
  `ref` varchar(255) DEFAULT NULL,
  `violations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`violations`)),
  `value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `reason` text DEFAULT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'pending',
  `decided_by` char(36) DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `decision_note` text DEFAULT NULL,
  `created_by` char(36) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `login` varchar(255) NOT NULL,
  `token` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`login`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `permission_user`;
CREATE TABLE `permission_user` (
  `user_id` char(36) NOT NULL,
  `permission_id` varchar(64) NOT NULL,
  `until` date DEFAULT NULL,
  `max_amount` decimal(12,2) DEFAULT NULL,
  `granted_by` char(36) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`user_id`,`permission_id`),
  KEY `permission_user_permission_id_foreign` (`permission_id`),
  CONSTRAINT `permission_user_permission_id_foreign` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `permission_user_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions` (
  `id` varchar(64) NOT NULL,
  `grp` varchar(64) NOT NULL,
  `label` varchar(255) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `permissions_grp_index` (`grp`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `po_lines`;
CREATE TABLE `po_lines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `po_id` bigint(20) unsigned NOT NULL,
  `line` int(11) NOT NULL,
  `item_id` bigint(20) unsigned NOT NULL,
  `qty` decimal(12,3) NOT NULL,
  `price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `received` decimal(12,3) NOT NULL DEFAULT 0.000,
  PRIMARY KEY (`id`),
  UNIQUE KEY `po_lines_po_id_line_unique` (`po_id`,`line`),
  KEY `po_lines_item_id_foreign` (`item_id`),
  CONSTRAINT `po_lines_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `po_lines_po_id_foreign` FOREIGN KEY (`po_id`) REFERENCES `purchase_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3516 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `price_log`;
CREATE TABLE `price_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `item_id` bigint(20) unsigned NOT NULL,
  `old_price` decimal(12,2) DEFAULT NULL,
  `new_price` decimal(12,2) NOT NULL,
  `by` char(36) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `price_log_item_id_foreign` (`item_id`),
  CONSTRAINT `price_log_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `prices`;
CREATE TABLE `prices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `item_id` bigint(20) unsigned NOT NULL,
  `location_id` varchar(64) NOT NULL,
  `channel` varchar(10) NOT NULL DEFAULT 'direct',
  `price` decimal(12,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `prices_item_id_location_id_channel_unique` (`item_id`,`location_id`,`channel`),
  KEY `prices_location_id_foreign` (`location_id`),
  CONSTRAINT `prices_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `prices_location_id_foreign` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=603 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



DROP TABLE IF EXISTS `prod_orders`;
CREATE TABLE `prod_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `no` bigint(20) unsigned NOT NULL,
  `item_id` bigint(20) unsigned NOT NULL,
  `qty` decimal(12,3) NOT NULL,
  `due` date NOT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'planned',
  `note` text DEFAULT NULL,
  `created_by` char(36) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `prod_orders_no_unique` (`no`),
  KEY `prod_orders_item_id_foreign` (`item_id`),
  CONSTRAINT `prod_orders_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=484 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `prod_steps`;
CREATE TABLE `prod_steps` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint(20) unsigned NOT NULL,
  `step` int(11) NOT NULL,
  `section_id` varchar(64) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'waiting',
  `in_weight` decimal(12,3) DEFAULT NULL,
  `out_weight` decimal(12,3) DEFAULT NULL,
  `waste` decimal(12,3) DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `ended_at` timestamp NULL DEFAULT NULL,
  `started_by` char(36) DEFAULT NULL,
  `ended_by` char(36) DEFAULT NULL,
