  UNIQUE KEY `prod_steps_order_id_step_unique` (`order_id`,`step`),
  KEY `prod_steps_section_id_foreign` (`section_id`),
  CONSTRAINT `prod_steps_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `prod_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `prod_steps_section_id_foreign` FOREIGN KEY (`section_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1670 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `purchase_orders`;
CREATE TABLE `purchase_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
