  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stock_counts_count_number_unique` (`count_number`),
  KEY `stock_counts_location_id_status_index` (`location_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `stock_moves`;
CREATE TABLE `stock_moves` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `at` timestamp NULL DEFAULT NULL,
  `item_id` bigint(20) unsigned NOT NULL,
  `location_id` varchar(64) NOT NULL,
  `qty` decimal(12,3) NOT NULL,
  `kind` varchar(20) NOT NULL,
  `reason` text DEFAULT NULL,
  `ref` varchar(255) DEFAULT NULL,
  `box_sn` bigint(20) unsigned DEFAULT NULL,
  `unit_cost` decimal(12,2) DEFAULT NULL,
  `by` char(36) DEFAULT NULL,
  `shift_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stock_moves_location_id_foreign` (`location_id`),
  KEY `stock_moves_box_sn_foreign` (`box_sn`),
  KEY `stock_moves_item_id_location_id_index` (`item_id`,`location_id`),
  KEY `stock_moves_ref_index` (`ref`),
  KEY `stock_moves_shift_id_index` (`shift_id`),
  CONSTRAINT `stock_moves_box_sn_foreign` FOREIGN KEY (`box_sn`) REFERENCES `boxes` (`sn`) ON DELETE SET NULL,
  CONSTRAINT `stock_moves_item_id_foreign` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stock_moves_location_id_foreign` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `stock_moves_shift_id_foreign` FOREIGN KEY (`shift_id`) REFERENCES `shifts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=46010 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


















































































DROP TABLE IF EXISTS `supplier_payments`;
CREATE TABLE `supplier_payments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `no` bigint(20) unsigned NOT NULL,
