  UNIQUE KEY `transfer_boxes_transfer_id_box_sn_unique` (`transfer_id`,`box_sn`),
  KEY `transfer_boxes_box_sn_foreign` (`box_sn`),
  CONSTRAINT `transfer_boxes_box_sn_foreign` FOREIGN KEY (`box_sn`) REFERENCES `boxes` (`sn`) ON DELETE CASCADE,
  CONSTRAINT `transfer_boxes_transfer_id_foreign` FOREIGN KEY (`transfer_id`) REFERENCES `transfers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5951 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `transfers`;
CREATE TABLE `transfers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `no` bigint(20) unsigned NOT NULL,
  `from_loc` varchar(64) NOT NULL,
  `to_loc` varchar(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'transit',
  `reason` text DEFAULT NULL,
  `note` text DEFAULT NULL,
  `sent_by` char(36) DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL,
  `recv_by` char(36) DEFAULT NULL,
  `recv_at` timestamp NULL DEFAULT NULL,
  `trip_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transfers_no_unique` (`no`),
  KEY `transfers_from_loc_foreign` (`from_loc`),
  KEY `transfers_to_loc_foreign` (`to_loc`),
  CONSTRAINT `transfers_from_loc_foreign` FOREIGN KEY (`from_loc`) REFERENCES `locations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `transfers_to_loc_foreign` FOREIGN KEY (`to_loc`) REFERENCES `locations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=702 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `trip_boxes`;
CREATE TABLE `trip_boxes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `trip_id` bigint(20) unsigned NOT NULL,
  `crate_id` varchar(32) NOT NULL,
  `box_sn` bigint(20) unsigned NOT NULL,
  `removed` tinyint(1) NOT NULL DEFAULT 0,
  `at` timestamp NULL DEFAULT NULL,
  `by` char(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `trip_boxes_crate_id_foreign` (`crate_id`),
  KEY `trip_boxes_box_sn_foreign` (`box_sn`),
  KEY `trip_boxes_trip_id_removed_index` (`trip_id`,`removed`),
  CONSTRAINT `trip_boxes_box_sn_foreign` FOREIGN KEY (`box_sn`) REFERENCES `boxes` (`sn`) ON DELETE CASCADE,
  CONSTRAINT `trip_boxes_crate_id_foreign` FOREIGN KEY (`crate_id`) REFERENCES `crates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `trip_boxes_trip_id_foreign` FOREIGN KEY (`trip_id`) REFERENCES `trips` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4838 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `trip_crates`;
CREATE TABLE `trip_crates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `trip_id` bigint(20) unsigned NOT NULL,
  `crate_id` varchar(32) NOT NULL,
  `to_loc` varchar(64) NOT NULL,
  `closed` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trip_crates_trip_id_crate_id_unique` (`trip_id`,`crate_id`),
  KEY `trip_crates_crate_id_foreign` (`crate_id`),
  KEY `trip_crates_to_loc_foreign` (`to_loc`),
  CONSTRAINT `trip_crates_crate_id_foreign` FOREIGN KEY (`crate_id`) REFERENCES `crates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `trip_crates_to_loc_foreign` FOREIGN KEY (`to_loc`) REFERENCES `locations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `trip_crates_trip_id_foreign` FOREIGN KEY (`trip_id`) REFERENCES `trips` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2520 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `trips`;
CREATE TABLE `trips` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `no` bigint(20) unsigned NOT NULL,
  `truck` varchar(255) NOT NULL,
  `driver` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'loading',
  `created_by` char(36) DEFAULT NULL,
  `left_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trips_no_unique` (`no`)
) ENGINE=InnoDB AUTO_INCREMENT=392 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` char(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `is_owner` tinyint(1) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `is_driver` tinyint(1) NOT NULL DEFAULT 0,
  `home_location_id` varchar(64) DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_phone_unique` (`phone`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_is_owner_index` (`is_owner`),
  KEY `users_active_index` (`active`),
  KEY `users_home_location_id_index` (`home_location_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS=1;
